mapper.select:
SELECT note_seq, version, title, summary, release_date, target, use_yn, sort_order, created_by, created_at, updated_by, updated_at FROM tb_release_note
AND (version LIKE '%' || #{keyword} || '%' OR title LIKE '%' || #{keyword} || '%')
AND target = #{target}
AND use_yn = #{useYn}
ORDER BY release_date DESC NULLS LAST, version DESC, note_seq DESC
